#!/usr/bin/env python3
"""Writes src/unimplemented.cc: a definition for every V8 API function that
the link still misses, each of which stops the program with its name.

The input is wasm-ld's list of undefined symbols (demangled), for example

    undefined symbol: v8::Function::Call(v8::Local<v8::Context>, ...)

A demangled name carries the parameter types but not the return type, so the
return type is left to the compiler: the definition uses a trailing return
type of `decltype` of a call with those parameter types, which picks the
declared overload.

    generate-stubs.py link.log > src/unimplemented.cc
"""

import re
import sys

PREFIX = 'undefined symbol: '


def split_params(text):
    """Splits a demangled parameter list at top-level commas."""
    params, depth, current = [], 0, ''
    for c in text:
        if c in '<(':
            depth += 1
        elif c in '>)':
            depth -= 1
        if c == ',' and depth == 0:
            params.append(current.strip())
            current = ''
        else:
            current += c
    if current.strip():
        params.append(current.strip())
    return params


def parse(symbol):
    """Returns (qualified name, params, cv) or None for non-functions."""
    # Find the parameter list: the last top-level parenthesized group.
    depth = 0
    end = None
    for i in range(len(symbol) - 1, -1, -1):
        c = symbol[i]
        if c == ')':
            if depth == 0:
                end = i
            depth += 1
        elif c == '(':
            depth -= 1
            if depth == 0 and end is not None:
                name = symbol[:i]
                params = split_params(symbol[i + 1:end])
                if params == ['void']:
                    params = []
                cv = symbol[end + 1:].strip()
                return name, params, cv
    return None


def scope_and_member(name):
    """Splits `a::b::C::f` at the last top-level `::`."""
    depth = 0
    for i in range(len(name) - 1, 0, -1):
        c = name[i]
        if c == '>':
            depth += 1
        elif c == '<':
            depth -= 1
        elif c == ':' and name[i - 1] == ':' and depth == 0:
            return name[:i - 1], name[i + 1:]
    return '', name


def definition(symbol):
    parsed = parse(symbol)
    if parsed is None:
        return None
    name, params, cv = parsed
    scope, member = scope_and_member(name)
    param_list = ', '.join(params)
    message = symbol.replace('\\', '\\\\').replace('"', '\\"')
    body = '{ ::v8::shim::Unimplemented("%s"); }' % message
    short = scope_and_member(scope)[1] if scope else ''
    if member == short or member == '~' + short:
        # Constructor or destructor.
        return '%s(%s) %s' % (name, param_list, body)
    args = ', '.join('std::declval<%s>()' % p for p in params)
    obj = 'std::declval<const %s&>()' % scope if 'const' in cv else 'std::declval<%s&>()' % scope
    if scope and is_class(scope):
        call = '%s.%s(%s)' % (obj, member, args)
    else:
        call = '%s(%s)' % (name, args)
    return 'auto %s(%s) %s -> decltype(%s) %s' % (name, param_list, cv, call, body)


# Scopes that are namespaces rather than classes.
NAMESPACES = {
    'v8', 'v8::platform', 'v8::platform::tracing', 'v8::internal',
    'v8::api_internal', 'cppgc', 'cppgc::internal', 'v8::debug',
}


def is_class(scope):
    return scope not in NAMESPACES


def main():
    symbols = []
    for line in open(sys.argv[1]):
        line = line.strip()
        index = line.find(PREFIX)
        if index < 0:
            continue
        symbol = line[index + len(PREFIX):]
        if symbol not in symbols:
            symbols.append(symbol)
    out = [
        '// Generated by tools/generate-stubs.py. Each function is a part of the',
        '// V8 API that the shim does not implement yet; calling it stops the',
        '// program with the function\'s name.',
        '',
        '#include <utility>',
        '',
        '#include "src/all-api.h"',
        '#include "src/shim.h"',
        '',
    ]
    skipped = []
    for symbol in sorted(symbols):
        text = definition(symbol)
        if text is None:
            skipped.append(symbol)
            continue
        out.append(text)
    for symbol in skipped:
        out.append('// Not a function, define by hand: %s' % symbol)
    print('\n'.join(out))


if __name__ == '__main__':
    main()
